<script setup lang="ts">
import {onBeforeUnmount,ref,watch} from 'vue';import {api} from '../api';import type {InterimCandidate} from '../contracts';import {reviewRequestId} from '../utils/interim-review';import {useAuth} from '../composables/auth';
import Button from './ui/Button.vue';import Select from './ui/Select.vue';import InterimReviewDetails from './InterimReviewDetails.vue';
const props=defineProps<{scanId:number;attempt:number;running:boolean;selected:InterimCandidate[]}>(),emit=defineEmits<{clear:[]}>();const {canOperate}=useAuth();
const groups=ref<number[]>([]),group=ref(0),ack=ref(false),grouping=ref('exact'),reason=ref(''),busy=ref(false),error=ref('');let generation=0,requestId='',disposed=false;
async function load(){const gen=++generation;try{const ids=await api.interimReviews(props.scanId,props.attempt);if(disposed||gen!==generation)return;if(!Array.isArray(ids)||ids.some(n=>!Number.isSafeInteger(n)||n<1))throw new Error('复核历史格式无效');groups.value=ids;}catch(e){if(!disposed&&gen===generation)error.value='复核历史读取失败：'+(e as Error).message}}
async function create(){if(!ack.value||busy.value||!canOperate.value||!props.selected.length||props.running)return;const gen=generation,id=props.scanId;busy.value=true;error.value='';requestId ||= reviewRequestId();try{const result=await api.createInterimReview(id,{schemaVersion:1,requestId,members:props.selected.map(c=>({execution:{taskId:String(id),attempt:props.attempt},candidateId:c.id,artifactSha256:c.artifact})),grouping:grouping.value as 'exact'|'manual',groupingReason:reason.value,acknowledgeUnknownCost:true});if(disposed||gen!==generation)return;group.value=result.groupId;ack.value=false;requestId='';await load()}catch(e){if(!disposed&&gen===generation)error.value='独立复核未创建：'+(e as Error).message}finally{busy.value=false}}
watch(()=>[props.scanId,props.attempt],()=>{generation++;groups.value=[];group.value=0;ack.value=false;requestId='';error.value='';void load()},{immediate:true});
watch(()=>[props.selected.map(c=>c.id+':'+c.artifact).join(','),grouping.value,reason.value],()=>{requestId='';ack.value=false});onBeforeUnmount(()=>{disposed=true;generation++});
</script>
<template><section class="review-panel" aria-label="中间候选独立复核"><header><h3>独立复核与归档</h3><Button variant="ghost" size="sm" @click="load">刷新候选复核历史</Button></header><p>选择候选后可冻结证据并独立复核，不重跑整轮扫描。相同冻结源码中的精确重复组复用已有复核任务；相似问题不会自动合并。</p><p v-if="error" role="alert" class="review-error">{{error}}</p>
 <div v-if="canOperate&&selected.length" class="review-selection"><div>已选择 {{selected.length}} 条候选 <Button variant="ghost" size="sm" :disabled="busy" @click="emit('clear')">清除候选选择</Button></div><Select v-model="grouping" :options="[{value:'exact',label:'同一精确重复组'},{value:'manual',label:'手动合并为同一问题'}]" aria-label="复核分组方式"/><label v-if="grouping==='manual'">合并依据<textarea v-model="reason" aria-label="候选合并依据" maxlength="2000" rows="2"/></label><label class="review-consent"><input v-model="ack" type="checkbox" :disabled="busy||running"/>本次独立复核将调用模型，费用未知且不受原扫描预算控制；不执行应用、测试或 PoC。</label><Button size="sm" variant="outline" :disabled="!ack||busy||running||(grouping==='manual'&&!reason.trim())" :loading="busy" @click="create">冻结证据并独立复核</Button><p v-if="running">原执行仍在运行，请待结束后冻结选定版本。</p></div>
 <p v-else-if="!groups.length">{{canOperate?'勾选候选记录后可准备独立复核。':'尚无候选独立复核记录；当前账户仅可读取证据。'}}</p>
 <div v-if="groups.length" class="review-groups"><span>关联复核组</span><Button v-for="id in groups" :key="id" size="sm" :variant="group===id?'secondary':'ghost'" :aria-pressed="group===id" @click="group=id">复核组 #{{id}}</Button></div><InterimReviewDetails v-if="group" :key="group" :group-id="group"/>
 </section></template>
<style scoped>
.review-panel{border-top:1px solid var(--border-default);padding-top:var(--space-3);margin-top:var(--space-3);font-size:var(--font-size-sm);min-width:0}header,.review-groups{display:flex;align-items:center;flex-wrap:wrap;gap:var(--space-2)}header{justify-content:space-between}h3{font-size:var(--font-size-sm);font-weight:var(--font-weight-medium);margin:0}p{color:var(--text-secondary);line-height:var(--line-height-body);margin-block:var(--space-2)}.review-selection{display:flex;align-items:flex-start;flex-direction:column;gap:var(--space-2);margin-block:var(--space-3)}label{display:flex;flex-direction:column;gap:var(--space-1);width:100%}.review-consent{flex-direction:row;align-items:flex-start;line-height:var(--line-height-body)}textarea{border:1px solid var(--border-default);border-radius:var(--radius-sm);padding:var(--space-2);background:var(--surface-primary);color:var(--text-primary);max-width:640px;width:100%;box-sizing:border-box}.review-error{color:var(--state-danger)}.review-groups{padding-block:var(--space-2)}
</style>
